/** Third-party notices for **Settings → About → Licences** (`/licenses`, plan 30). The data is
 *  `thirdPartyLicenses.json`, generated by `npm run licenses` (scripts/licenses.mjs) from the
 *  production dependency tree and published as docs/third-party-licenses.md. */
import data from './thirdPartyLicenses.json';

export interface LicensedPackage {
  name: string;
  version: string;
  /** SPDX expression as the package declares it, e.g. `MIT` or `(MIT OR Apache-2.0)`. */
  license: string;
  repository: string | null;
  copyright: string[];
  /** Key into `LicenseData.texts`, or null when the package ships no licence file. */
  text: string | null;
}

export interface LicenseData {
  schema: string;
  app: string;
  /** package.json `dependencies` at generation time (the test checks they are all listed). */
  direct: string[];
  packages: LicensedPackage[];
  /** Distinct licence texts (copyright lines removed), by id. */
  texts: Record<string, string>;
}

export const THIRD_PARTY_LICENSES = data as LicenseData;

/** How many packages use each licence, most used first. */
export function licenceSummary(d: LicenseData): { license: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const p of d.packages) counts.set(p.license, (counts.get(p.license) ?? 0) + 1);
  return [...counts.entries()]
    .map(([license, count]) => ({ license, count }))
    .sort((a, b) => b.count - a.count || a.license.localeCompare(b.license, 'en'));
}

/** Packages whose name or licence contains `query` (case-insensitive); all of them when the query
 *  is blank. */
export function filterPackages(d: LicenseData, query: string): LicensedPackage[] {
  const q = query.trim().toLowerCase();
  if (!q) return d.packages;
  return d.packages.filter(
    (p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q),
  );
}

/** A stable key per package entry (two versions of one package can both be listed). */
export function packageKey(p: LicensedPackage): string {
  return `${p.name}@${p.version}`;
}
